-- Drift schema v1 (pre-FE-604), captured from the generated AppDatabase. Used by the v1→v2 migration test.
CREATE TABLE "cached_titles" ("id" INTEGER NOT NULL, "title" TEXT NOT NULL, "media_type" TEXT NOT NULL, "poster_path" TEXT NULL, "backdrop_path" TEXT NULL, "overview" TEXT NULL, "release_date" TEXT NULL, "genres" TEXT NULL, "streaming_services" TEXT NULL, "is_anime" INTEGER NOT NULL DEFAULT 0 CHECK ("is_anime" IN (0, 1)), "total_seasons" INTEGER NULL, "total_episodes" INTEGER NULL, "updated_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), PRIMARY KEY ("id", "media_type"));
CREATE TABLE "local_rankings" ("show_id" INTEGER NOT NULL, "media_type" TEXT NOT NULL, "title" TEXT NOT NULL, "poster_path" TEXT NULL, "rank_position" INTEGER NOT NULL, "calculated_score" REAL NOT NULL, "bracket" TEXT NULL, "sync_status" TEXT NOT NULL DEFAULT 'SYNCED', "updated_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), PRIMARY KEY ("show_id", "media_type"));
CREATE TABLE "offline_duel_queue" ("id" TEXT NOT NULL, "winner_title_id" INTEGER NOT NULL, "loser_title_id" INTEGER NOT NULL, "media_type" TEXT NOT NULL, "round_number" INTEGER NOT NULL, "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), "sync_status" TEXT NOT NULL DEFAULT 'PENDING', PRIMARY KEY ("id"));
CREATE TABLE "watchlist_cache" ("title_id" INTEGER NOT NULL, "media_type" TEXT NOT NULL, "title" TEXT NOT NULL, "poster_path" TEXT NULL, "saved_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), "sync_status" TEXT NOT NULL DEFAULT 'SYNCED', PRIMARY KEY ("title_id", "media_type"));
